d_{k'}^\ur, \textrm{ or }d_{k'}^\Iw - d_{k'}^\ur\textrm{  belongs to }\big(\tfrac 12d_k^\Iw-\ell, \tfrac 12 d_k^\Iw+\ell\big)
,
